import * as THREE from 'three';
import { CONFIG } from '../config';
import { scene } from '../core/renderer';
import { rand, clamp } from '../common/math';
import { patchWindows, patchFarGlow } from '../common/shaders';

/* ============================ Đô thị ============================ */
export function buildCity() {
  const items: { x: number; z: number; w: number; d: number; h: number; c: number }[] = [];
  const palette = [0xf3f0e7, 0xeae2cf, 0xdadcdc, 0xcfe0e7, 0xdde8df, 0xc8ced4, 0xf6f6f2, 0xe6dccb];
  const avoid = (_x: number, z: number) => Math.abs(z) < 48 || Math.abs(z - CONFIG.ttl.z) < 40;
  const place = (x0: number, x1: number, near: number, beach: boolean) => {
    const step = 36;
    for (let gx = x0; gx < x1; gx += step) for (let gz = -1800; gz < 1800; gz += step) {
      const ix = Math.round(gx / step), iz = Math.round(gz / step);
      if (ix % 5 === 0 || iz % 5 === 0) continue;  // chừa đường phố
      if (avoid(gx, gz) || rand() < 0.16) continue;
      const nearR = 1 - clamp((Math.abs(gx - near)) / 900, 0, 1);
      let h = 9 + rand() * 26 + nearR * rand() * 65 + (rand() < 0.05 ? 55 : 0);
      if (beach && gx > 1290) h = 45 + rand() * 115; // khách sạn ven biển Mỹ Khê
      items.push({ x: gx + (rand() - 0.5) * 6, z: gz + (rand() - 0.5) * 6, w: 14 + rand() * 15, d: 14 + rand() * 15, h, c: palette[Math.floor(rand() * palette.length)] });
    }
  };
  place(-2000, -330, -330, false); // bờ Tây — trung tâm Hải Châu
  place(340, 1450, 340, true);      // bờ Đông — Sơn Trà
  // Gom thành cụm, mỗi cụm là một LOD (gần: có cửa sổ; xa: khối trơn)
  const cell = 900, clusters = new Map<string, typeof items>();
  for (const b of items) { const key = `${Math.floor(b.x / cell)}_${Math.floor(b.z / cell)}`; if (!clusters.has(key)) clusters.set(key, []); clusters.get(key).push(b); }
  const geo = new THREE.BoxGeometry(1, 1, 1).translate(0, 0.5, 0);
  const nearMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.75, metalness: 0.05 });
  patchWindows(nearMat, { perBuilding: true });
  const farMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 });
  patchFarGlow(farMat);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), s = new THREE.Vector3(), col = new THREE.Color();
  for (const list of clusters.values()) {
    const cx = list.reduce((a, b) => a + b.x, 0) / list.length, cz = list.reduce((a, b) => a + b.z, 0) / list.length;
    const near = new THREE.InstancedMesh(geo, nearMat, list.length), far = new THREE.InstancedMesh(geo, farMat, list.length);
    list.forEach((b, i) => {
      m.compose(v.set(b.x - cx, CONFIG.landY, b.z - cz), q, s.set(b.w, b.h, b.d));
      near.setMatrixAt(i, m); far.setMatrixAt(i, m); col.setHex(b.c); near.setColorAt(i, col); far.setColorAt(i, col.multiplyScalar(0.92));
    });
    near.castShadow = true; near.receiveShadow = true;
    const lod = new THREE.LOD(); lod.position.set(cx, 0, cz);
    lod.addLevel(near, 0); lod.addLevel(far, 2200); lod.addLevel(new THREE.Object3D(), 8000);
    scene.add(lod);
  }
}
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { CONFIG } from '../config';
import { scene } from '../core/renderer';
import { MAT } from '../core/materials';
import { shadowed } from '../common/geometry';
import { HR_HOLES } from '../bridges/han-tunnel/profile';

/* ============================ Bờ sông Hàn & mặt đất ============================ */
export function buildRiverBanks() {
  const B = CONFIG.bankX, Y = CONFIG.landY;
  // Bờ Tây (trung tâm) và bờ Đông (Sơn Trà / Mỹ Khê); phía Bắc là vịnh Đà Nẵng
  const landGeos = [];
  const box = (x0: number, x1: number, z0: number, z1: number, y0: number, y1: number) => { const b = new THREE.BoxGeometry(x1 - x0, y1 - y0, z1 - z0); b.translate((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2); return b; };
  // khoét hai hố cho máng hầm hở của Hầm vượt sông Hàn (không dùng rand nên không ảnh hưởng chuỗi ngẫu nhiên)
  const carved = (x0: number, x1: number, z0: number, z1: number) => {
    let cur = x0;
    for (const h of HR_HOLES.filter((q) => q.x0 >= x0 && q.x1 <= x1).sort((a, b) => a.x0 - b.x0)) {
      landGeos.push(box(cur, h.x0, z0, z1, -6, Y), box(h.x0, h.x1, z0, h.z0, -6, Y), box(h.x0, h.x1, h.z1, z1, -6, Y)); cur = h.x1;
    }
    landGeos.push(box(cur, x1, z0, z1, -6, Y));
  };
  carved(-14000, -B, -2600, 14000);
  carved(B, 1480, -2300, 14000);
  scene.add(shadowed(new THREE.Mesh(mergeGeometries(landGeos), MAT.land), false, true));
  // Bãi biển Mỹ Khê
  const sand = new THREE.Mesh(box(1480, 1600, -2300, 14000, -6, 1.2), MAT.sand); sand.receiveShadow = true; scene.add(sand);
  // Kè đá hai bờ (tường đứng) + lan can thấp
  const walls = [box(-B - 2, -B, -2600, 14000, -3, Y + 0.5), box(B, B + 2, -2300, 14000, -3, Y + 0.5)];
  const wallGeo = mergeGeometries(walls);
  // UV lặp theo chiều dài kè
  scene.add(shadowed(new THREE.Mesh(wallGeo, MAT.stone), false, true));
  // Dải đi bộ ven sông
  const prom = [box(-B - 26, -B - 2, -2600, 14000, Y, Y + 0.05), box(B + 2, B + 26, -2300, 14000, Y, Y + 0.05)];
  scene.add(shadowed(new THREE.Mesh(mergeGeometries(prom), MAT.paver), false, true));
}
/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
import { multiParams } from './params';

export type ClientMsg =
  | { t: 'join'; name: string; kind?: 'walk' }   // kind: 'walk' = xin chỗ đi dạo; không có = chỗ bay (khách cũ)
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number; ts?: number }   // ts: giờ gửi theo đồng hồ của khách (ms); máy chủ cũ bỏ qua
  | { t: 'pos'; x: number; y: number; z: number; yaw: number; pose: number; ts?: number }   // người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh), không có bank
  | { t: 'hb' }
  | { t: 'leave' };

export interface Flyer { slot: number; name: string }

export type Kind = 'fly' | 'walk';

// f: mỗi phần tử [slot, x, y, z, yaw, bank, giờ gửi (ms)]; chỉ gồm slot có vị trí mới. Giờ gửi = ts của khách, khách cũ không gửi ts thì là giờ máy chủ nhận;
// mỗi slot một trục giờ riêng, khách nhận tự quy đổi. Máy chủ cũ (trước bản sửa giật) gửi 6 phần tử và phát lại vị trí cũ của mọi slot: khách mới nhận được cả hai dạng.
// Đi dạo: lobby thêm walkers (flyers chỉ có người bay), pos thêm w (mỗi phần tử [slot, x, y, z, yaw, pose, giờ gửi]; f luôn có, có thể rỗng); khách cũ bỏ qua trường lạ
export type ServerMsg =
  | { t: 'lobby'; flyers: Flyer[]; walkers?: Flyer[] }
  | { t: 'joined'; slot: number; kind?: 'walk' }
  | { t: 'rejected'; why: 'full' | 'name'; kind?: 'walk' }
  | { t: 'pos'; f: number[][]; w?: number[][] }
  | { t: 'released' };

// Ký tự trông như khoảng trống dù thuộc nhóm chữ/ký hiệu (chữ đệm Hangul, chữ nổi trống, nguyên âm ẩn Khmer): không tính là chữ thấy được
const BLANK = /[\u115F\u1160\u3164\uFFA0\u2800\u17B4\u17B5]/gu;
const VISIBLE = /[\p{L}\p{N}\p{S}\p{P}]/u;

/* Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng.
   null nếu: rỗng; không có chữ/số/ký hiệu/dấu câu nào thấy được; quá nameMax grapheme; một grapheme quá graphemeCpMax code point (chồng dấu); tổng quá nameCpMax code point */
export function exSanitizeName(raw: string): string | null {
  if (typeof raw !== 'string') return null;
  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200D' ? c : '')).trim();
  if (!s || !VISIBLE.test(s.replace(BLANK, ''))) return null;
  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
  let n = 0, cps = 0;
  for (const g of seg.segment(s)) {
    let k = 0;
    for (const _ of g.segment) k++;
    cps += k;
    if (++n > multiParams.nameMax || k > multiParams.graphemeCpMax || cps > multiParams.nameCpMax) return null;
  }
  return s;
}
/* ===== Phòng bầu trời chung: logic thuần, không phụ thuộc Cloudflare (Durable Object bọc ngoài) ===== */
import { multiParams as P } from '../../../src/explore/multi/params';
import { exSanitizeName } from '../../../src/explore/multi/protocol';
import type { ServerMsg, Flyer, Kind } from '../../../src/explore/multi/protocol';
import { exIsBad } from './badwords';

export type Out = { to: string | 'all'; msg: ServerMsg };

// pos: [slot, x, y, z, yaw, bank (người đi dạo: pose), giờ gửi]; giờ gửi = ts của khách (khách mới) hoặc giờ máy chủ nhận (khách cũ); dirty: có vị trí mới chưa phát
interface Slot { id: string; name: string; seen: number; pos: number[] | null; dirty: boolean }
interface Conn { stamps: number[] }

const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));
const wrapPi = (a: number) => a - Math.round(a / (2 * Math.PI)) * 2 * Math.PI;   // góc về [−π, π]

export class SkyRoom {
  private conns = new Map<string, Conn>();
  private slots: (Slot | null)[] = new Array(P.slots).fill(null);
  private walkSlots: (Slot | null)[] = new Array(P.stroll.slots).fill(null);   // nhóm chỗ đi dạo, tách khỏi nhóm bay
  private lastBroadcast = -Infinity;

  private lobby(): Out {
    const flyers: Flyer[] = [];
    const walkers: Flyer[] = [];
    this.slots.forEach((s, i) => { if (s) flyers.push({ slot: i, name: s.name }); });
    this.walkSlots.forEach((s, i) => { if (s) walkers.push({ slot: i, name: s.name }); });
    return { to: 'all', msg: { t: 'lobby', flyers, walkers } };
  }

  connect(id: string, now: number): Out[] | null {
    if (!this.conns.has(id) && this.conns.size >= P.maxConns) return null;
    this.conns.set(id, { stamps: [] });
    return [{ to: id, msg: this.lobby().msg }];
  }

  slotOf(id: string): number { return this.slots.findIndex(s => s !== null && s.id === id); }   // slot bay, -1 nếu không bay

  walkSlotOf(id: string): number { return this.walkSlots.findIndex(s => s !== null && s.id === id); }   // slot đi dạo, -1 nếu không đi dạo

  kindOf(id: string): Kind | null { return this.slotOf(id) >= 0 ? 'fly' : this.walkSlotOf(id) >= 0 ? 'walk' : null; }

  hasFlyers(): boolean { return this.slots.some(s => s !== null) || this.walkSlots.some(s => s !== null); }   // còn ai giữ slot (bay hoặc đi): giữ alarm quét

  /* Giờ có tin cuối của người giữ slot (để lưu vào attachment); -1 nếu không giữ slot */
  seenOf(id: string): number {
    const i = this.slotOf(id);
    if (i >= 0) return this.slots[i].seen;
    const w = this.walkSlotOf(id);
    return w < 0 ? -1 : this.walkSlots[w].seen;
  }

  /* Dựng lại sau hibernation. seen lấy từ attachment nếu có; không có (attachment cũ) thì coi như vừa im lặng gần hết hạn:
     người còn bay có một chu kỳ nhịp sống để lên tiếng, người đã chết không được gia hạn thêm mỗi lần thức dậy */
  restore(list: { id: string; slot: number; name: string; seen?: number; kind?: 'walk' }[], now: number): void {
    for (const e of list) {
      const group = e.kind === 'walk' ? this.walkSlots : this.slots;
      if (e.slot < 0 || e.slot >= group.length) continue;
      if (!this.conns.has(e.id)) this.conns.set(e.id, { stamps: [] });
      const seen = typeof e.seen === 'number' && Number.isFinite(e.seen) ? Math.min(e.seen, now) : now - P.slotTimeoutMs + P.heartbeatMs;
      group[e.slot] = { id: e.id, name: e.name, seen, pos: null, dirty: false };
    }
  }

  message(id: string, raw: string, now: number): Out[] {
    const conn = this.conns.get(id);
    if (!conn || typeof raw !== 'string' || raw.length > P.maxMsgBytes) return [];
    let m: any;
    try { m = JSON.parse(raw); } catch { return []; }
    if (!m || typeof m !== 'object') return [];
    const kind = this.kindOf(id);
    const group = kind === 'walk' ? this.walkSlots : this.slots;
    const slot = kind === 'walk' ? this.walkSlotOf(id) : this.slotOf(id);
    switch (m.t) {
      case 'join': return this.onJoin(id, kind !== null, m.name, m.kind === 'walk', now);
      case 'leave': return this.release(id) ? [this.lobby()] : [];
      case 'hb': if (slot < 0) return []; group[slot].seen = now; return this.flush(now);
      case 'pos': return slot >= 0 ? this.onPos(conn, group[slot]!, slot, kind === 'walk', m, now) : [];
      default: return [];
    }
  }

  private onJoin(id: string, holding: boolean, rawName: unknown, walk: boolean, now: number): Out[] {
    if (holding) return [];
    const name = typeof rawName === 'string' ? exSanitizeName(rawName) : null;
    if (name === null || exIsBad(name)) return [{ to: id, msg: walk ? { t: 'rejected', why: 'name', kind: 'walk' } : { t: 'rejected', why: 'name' } }];
    const group = walk ? this.walkSlots : this.slots;
    const free = group.findIndex(s => s === null);
    if (free < 0) return [{ to: id, msg: walk ? { t: 'rejected', why: 'full', kind: 'walk' } : { t: 'rejected', why: 'full' } }];
    group[free] = { id, name, seen: now, pos: null, dirty: false };
    return [{ to: id, msg: walk ? { t: 'joined', slot: free, kind: 'walk' } : { t: 'joined', slot: free } }, this.lobby()];
  }

  private onPos(conn: Conn, s: Slot, slot: number, walk: boolean, m: any, now: number): Out[] {
    const { x, y, z, yaw, ts } = m;
    const tilt = walk ? m.pose : m.bank;   // người đi dạo gửi pose, người bay gửi bank; trường kia bị bỏ qua
    for (const v of [x, y, z, yaw, tilt]) if (typeof v !== 'number' || !Number.isFinite(v)) return [];
    conn.stamps = conn.stamps.filter(t => now - t < 1000);
    if (conn.stamps.length >= P.posMaxPerSec) return [];
    conn.stamps.push(now);
    s.seen = now;
    const stamp = typeof ts === 'number' && Math.abs(ts) <= Number.MAX_SAFE_INTEGER ? ts : now;   // ts ngoài ±2^53 (kể cả NaN/∞) coi như không gửi, tránh đẩy độ lệch giờ của khách thành ∞
    if (walk) {
      const B = P.stroll.bounds;
      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, P.stroll.yMin, P.stroll.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(Math.round(tilt), 0, P.stroll.poseMax), stamp];
    } else {
      s.pos = [slot, clamp(x, P.bounds.x0, P.bounds.x1), clamp(y, P.floor, P.ceiling), clamp(z, P.bounds.z0, P.bounds.z1), wrapPi(yaw), clamp(tilt, -P.bankMax, P.bankMax), stamp];
    }
    s.dirty = true;
    return this.flush(now);
  }

  /* Phát gói gộp các slot có vị trí mới (cách lần trước >= broadcastMs). Vị trí bị hãm trong cửa sổ vẫn dirty nên đi ở lần phát sau (pos hoặc hb của bất kỳ ai).
     Không phát lại vị trí cũ: khách cũ đóng dấu theo giờ nhận nên mẫu lặp làm dù đứng rồi vọt. Khách mới đặt mẫu theo e[6] */
  private flush(now: number): Out[] {
    if (now - this.lastBroadcast < P.broadcastMs) return [];
    const f: number[][] = [], w: number[][] = [];
    for (const t of this.slots) if (t && t.dirty) { f.push(t.pos!); t.dirty = false; }
    for (const t of this.walkSlots) if (t && t.dirty) { w.push(t.pos!); t.dirty = false; }
    if (!f.length && !w.length) return [];
    this.lastBroadcast = now;
    return [{ to: 'all', msg: w.length ? { t: 'pos', f, w } : { t: 'pos', f } }];
  }

  // Trả slot của kết nối; true nếu có slot được trả
  private release(id: string): boolean {
    const i = this.slotOf(id);
    if (i >= 0) { this.slots[i] = null; return true; }
    const w = this.walkSlotOf(id);
    if (w < 0) return false;
    this.walkSlots[w] = null;
    return true;
  }

  disconnect(id: string): Out[] {
    this.conns.delete(id);
    return this.release(id) ? [this.lobby()] : [];
  }

  sweep(now: number): Out[] {
    const out: Out[] = [];
    for (const group of [this.slots, this.walkSlots]) group.forEach((s, i) => {
      if (s && now - s.seen > P.slotTimeoutMs) { out.push({ to: s.id, msg: { t: 'released' } }); group[i] = null; }
    });
    if (out.length) out.push(this.lobby());
    return out;
  }
}

