/* Trụ cầu trong lòng sông */
export function buildPiers() {
  const half = CONFIG.mainTotal / 2; const xs = [-half];
  let x = -half; for (const s of CONFIG.mainSpans) { x += s; xs.push(x); }
  xs.push(...CONFIG.approachPiers);
  const colGeo = new THREE.CylinderGeometry(1, 1, 1, 18).translate(0, 0.5, 0);
  const boxGeo = new THREE.BoxGeometry(1, 1, 1);
  const cols = new THREE.InstancedMesh(colGeo, MAT.pier, xs.length * 2);
  const caps = new THREE.InstancedMesh(boxGeo, MAT.pier, xs.length * 2);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), s = new THREE.Vector3();
  let k = 0, c = 0;
  xs.forEach((px) => {
    const big = Math.abs(Math.abs(px) - 100) < 1; // chân vòm chính
    const r = big ? 2.8 : 2.0, top = deckY(px) - 3.4;
    for (const sz of [-1, 1]) { m.compose(v.set(px, -4, sz * 8.5), q, s.set(r, top + 4, r * 1.4)); cols.setMatrixAt(k++, m); }
    m.compose(v.set(px, -1, 0), q, s.set(big ? 16 : 11, 2.4, 28)); caps.setMatrixAt(c++, m);         // bệ trụ
    m.compose(v.set(px, top - 0.8, 0), q, s.set(big ? 7 : 5, 1.6, 25)); caps.setMatrixAt(c++, m);    // xà mũ
  });
  scene.add(shadowed(cols), shadowed(caps));
}
  const W = TTL.westEnd, E = TTL.eastEnd, B = CONFIG.bankX;
  // Trụ thân rộng: trong sông có bệ móng (vệt nước bám qua shader 'wet'); trên bờ đặt trên dải phân cách đường ven sông.
  // Trụ là hình tĩnh nên gộp chung vào khối bê tông (1 draw call) thay vì InstancedMesh.
  TTL.piers.forEach((x) => {
    const inRiver = Math.abs(x) < B, y0 = inRiver ? -3 : CONFIG.landY - 1, top = ttlRoadY(x) - TTL.girderDepth;
    bridge.concreteParts.push(prepColored(loftOct([2.6, 19], [2.6, 19], y0, top, [x, 0], [x, 0], 0.5)));
    if (inRiver) bridge.concreteParts.push(prepColored(boxAt(7, 6.6, 25, x, -2.7, 0, 4)));
  });
  // mố + tường chắn đường đắp hai đầu
  for (const [x, a, b] of [[W, -470, W], [E, E, 450]]) {
    bridge.concreteParts.push(prepColored(boxAt(6, ttlRoadY(x) - CONFIG.landY + 1, TTL.deckWidth + 1, x, (ttlRoadY(x) + CONFIG.landY - 1) / 2 - 0.3, 0)));
    bridge.concreteParts.push(prepColored(fillBlock(a, b, TTL.deckWidth, 0, CONFIG.landY - 0.5, (xx) => ttlRoadY(xx) - 0.05, 40), () => 0.82));
  }
}

/* [fixedSpans] 11 nhịp BTCT 33 m, trụ (InstancedMesh), trụ đón, mố, đường đắp */
export function shBuildFixedSpans(bridge: SongHanBridge) {
  const M = bridge.mats, hw = SH.hw, W = SH.westEnd, E = SH.eastEnd, F = SH.fixedStart, B = CONFIG.bankX;
  const sec = [[-hw, 0], [hw, 0], [hw, -0.35], [4.2, -0.6], [3.6, -SH.fixedDepth], [-3.6, -SH.fixedDepth], [-4.2, -0.6], [-hw, -0.35]];
  bridge.concreteParts.push(prepColored(extrudeAlongX(sec, W, -F, 200, shRoadY)), prepColored(extrudeAlongX(sec, F, E, 170, shRoadY)));
  // mố + đường đắp có kè: Tây ~2 m tới kè rồi dốc qua lề ven sông; Đông ~35 m lấn sông tới kè
  for (const [x, a, b] of [[W, -290, W], [E, E, 290]]) {
    bridge.concreteParts.push(prepColored(boxAt(5, shRoadY(x) + 4, SH.deckWidth + 1, x, shRoadY(x) / 2 - 2.3, 0)));
    bridge.concreteParts.push(prepColored(fillBlock(a, b, SH.deckWidth, 0, -3, (xx) => shRoadY(xx) - 0.05, 30), () => 0.82));
  }
  const rev = [boxAt(B - E, 4.8, 1.2, (E + B) / 2, 0.4, SH.hw + 0.6), boxAt(B - E, 4.8, 1.2, (E + B) / 2, 0.4, -SH.hw - 0.6)];
  const rv = shadowed(new THREE.Mesh(mergeGeometries(rev), MAT.stone), false, true); bridge.group.add(rv); bridge.farHide.push(rv);
  // trụ đón hai bên nhịp quay: xà mũ rộng có gối đỡ đầu cánh (khi đóng) và gối nhịp cố định
  for (const s of [-1, 1]) {
    const x = s * SH.restX;
    bridge.concreteParts.push(prepColored(loftOct([3.0, 3.6], [3.0, 3.6], -3, 9.2, [x, 0], [x, 0], 0.5)));
    bridge.concreteParts.push(prepColored(loftOct([3.0, 3.6], [4.8, 11], 9.2, 11.0, [x, 0], [x, 0], 0.4)));
    for (const z of [-3, 3]) {
      bridge.steelParts.push(boxAt(1.0, 0.5, 1.4, s * 60.9, 11.25, z).toNonIndexed());                 // gối đầu cánh
      bridge.steelParts.push(boxAt(1.0, 0.9, 1.4, s * 63.4, 11.45, z).toNonIndexed());                 // gối nhịp cố định
